// AddForm.vue — 逻辑
import { ref, defineEmits } from 'vue'
const emit = defineEmits(['add'])
const name = ref('')
const composer = ref('')
const image = ref('')
const period = ref('')
const errorMsg = ref('')
function handleSubmit() {
  errorMsg.value = ''
  if (!name.value.trim() || !composer.value.trim()) {
    errorMsg.value = '请至少填写曲名和作曲家'
    return
  }
  emit('add', {
    name: name.value.trim(),
    composer: composer.value.trim(),
    image: image.value.trim() || '',
    period: period.value || '未分类'
  })
  // 清空表单
  name.value = ''
  composer.value = ''
  image.value = ''
  period.value = ''
}

